print "output[194:234]: ", substr($s{output},194,40), "\n";
print "input[194:234]: ", substr($s{input},194,40), "\n";

print "\n--- Junction 2: egfp->flag ---\n";
print "output around egfp end/flag start ($egfp_start_idx+$j): ", substr($s{output},$egfp_start_idx+$j-20,60), "\n";

print "\n--- Junction 3: flag->snap ---\n";
print "output around flag end/snap start ($flag_start_idx+$fj): ", substr($s{output},$flag_start_idx+$fj-20,60), "\n";

print "\n--- Junction 4: snap->input ---\n";
print "output around snap end/input start ($snap_start_idx+$sj): ", substr($s{output},$snap_start_idx+$sj-20,60), "\n";

# Also print what the input region being replaced looks like
print "\n--- Input replaced region ---\n";
print "input[210:230]: ", substr($s{input},210,20), "\n";
print "input[680:700]: ", substr($s{input},680,20), "\n";
